/*Table structure for table `librocategoria` */

DROP TABLE IF EXISTS `librocategoria`;

CREATE TABLE `librocategoria` (
  `id` int NOT NULL AUTO_INCREMENT,
  `libroId` int NOT NULL,
  `categoriaId` int NOT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_libro_categoria` (`libroId`,`categoriaId`),
  KEY `idx_librocategoria_libro` (`libroId`),
  KEY `idx_librocategoria_categoria` (`categoriaId`),
  CONSTRAINT `librocategoria_ibfk_1` FOREIGN KEY (`libroId`) REFERENCES `libro` (`id`) ON DELETE CASCADE,
  CONSTRAINT `librocategoria_ibfk_2` FOREIGN KEY (`categoriaId`) REFERENCES `categoria` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

