/*Table structure for table `prestamo` */

DROP TABLE IF EXISTS `prestamo`;

CREATE TABLE `prestamo` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuarioId` int NOT NULL,
  `libroId` int NOT NULL,
  `fechaPrestamo` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fechaDevolucion` timestamp NULL DEFAULT NULL,
  `fechaDevolucionReal` timestamp NULL DEFAULT NULL,
  `estado` enum('prestado','devuelto','vencido','renovado') DEFAULT 'prestado',
  `renovaciones` int DEFAULT '0',
  `notas` text,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `usuarioId` (`usuarioId`),
  KEY `libroId` (`libroId`),
  KEY `idx_prestamo_estado` (`estado`),
  KEY `idx_prestamo_fechas` (`fechaPrestamo`,`fechaDevolucion`),
  CONSTRAINT `prestamo_ibfk_1` FOREIGN KEY (`usuarioId`) REFERENCES `usuario` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `prestamo_ibfk_2` FOREIGN KEY (`libroId`) REFERENCES `libro` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

