  `prioridad` enum('baja','media','alta') DEFAULT 'media',
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `usuarioId` (`usuarioId`),
  KEY `agenteId` (`agenteId`),
  KEY `idx_support_ticket_estado` (`estado`),
  KEY `idx_support_ticket_prioridad` (`prioridad`),
  CONSTRAINT `support_ticket_ibfk_1` FOREIGN KEY (`usuarioId`) REFERENCES `usuario` (`id`) ON DELETE CASCADE,
  CONSTRAINT `support_ticket_ibfk_2` FOREIGN KEY (`agenteId`) REFERENCES `support_agent` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

